  'This methods course prepares future elementary teachers to design inquiry-based, standards-aligned, inclusive social studies learning for grades K-6. Students learn to teach history, geography, civics, economics, culture, current events, media literacy, and democratic participation through sources, maps, children''s literature, local/community inquiry, fieldwork, discussion, performance assessment, and service learning.',
  $tessjson${"slug": "teaching-elementary-social-studies", "title": "Teaching Elementary Social Studies", "description": "This methods course prepares future elementary teachers to design inquiry-based, standards-aligned, inclusive social studies learning for grades K-6. Students learn to teach history, geography, civics, economics, culture, current events, media literacy, and democratic participation through sources, maps, children's literature, local/community inquiry, fieldwork, discussion, performance assessment, and service learning.", "topics": [{"id": "2d8c348d-32b3-45bd-a6b6-290aedfb43e0", "type": "topic", "title": "Social Studies Education, Democratic Citizenship, and the Elementary Teacher's Role", "description": "Students frame elementary social studies as inquiry-based preparation for informed, ethical, participatory democratic life.", "children": [{"id": "a19de07c-a2b0-44fe-be3a-5d4a8f2e2a33", "type": "subtopic", "title": "Purpose of elementary social studies", "children": [{"id": "d7cc8f28-2142-4c5e-a5ca-34891d73f017", "type": "concept", "title": "Democratic citizenship and public participation"}, {"id": "07bd1a40-eb81-4c01-aab1-4c1ce7e4f39f", "type": "concept", "title": "Community belonging and civic identity"}, {"id": "3fcc1708-efa8-4166-b34f-73120e8ee626", "type": "concept", "title": "Ethical reasoning, responsibility, and the public good"}], "description": "The point is to understand social studies as civic formation, not only coverage of facts."}, {"id": "12c6d114-f98f-4400-ae38-c67007a2abc3", "type": "subtopic", "title": "Disciplinary and interdisciplinary nature", "children": [{"id": "b86c8623-8290-479a-b6d8-aa8bdbff0e62", "type": "concept", "title": "Core social studies disciplines and habits of thinking"}, {"id": "5dd0ee4f-fe77-4b05-90b5-75e530c50235", "type": "concept", "title": "Connections to literacy, arts, science, mathematics, and local studies"}, {"id": "c15a5e42-cd10-4d94-95f2-aafd319cd919", "type": "concept", "title": "Big concepts such as power, change, culture, place, scarcity, and interdependence"}], "description": "Students see how history, geography, civics, economics, anthropology, and sociology work together in elementary inquiry."}, {"id": "9fc68ea4-26e2-45b9-94aa-7f1f1726f613", "type": "subtopic", "title": "Teacher stance and responsibilities", "children": [{"id": "e4cda04d-ad68-477e-ba82-8e461083390e", "type": "concept", "title": "Neutrality, balance, transparency, and intellectual honesty"}, {"id": "a90c56bc-b0cd-4e38-90a4-ec2dcec9353b", "type": "concept", "title": "Classroom norms for safety, dignity, and disagreement"}, {"id": "c3bba064-e9d4-418e-a744-6dbf692ec717", "type": "concept", "title": "Legal, ethical, family, and community considerations"}], "description": "Teachers learn to hold care, evidence, transparency, and professional judgment together."}]}, {"id": "6dcb8157-a11d-4de4-9fb3-796aab18f0b8", "type": "topic", "title": "C3 Framework, Inquiry Design, Standards, and Curriculum Alignment", "description": "This module turns standards into coherent inquiry units built around questions, evidence, disciplinary thinking, and civic action.", "children": [{"id": "755fd200-5fe9-4dc5-b41a-ffef493060b0", "type": "subtopic", "title": "C3 Framework dimensions", "children": [{"id": "063191df-867e-495c-aa21-1093519e8f32", "type": "concept", "title": "Developing questions and planning inquiries"}, {"id": "ba6e8d19-b5aa-4144-9456-2b3b10c1fdbe", "type": "concept", "title": "Applying disciplinary tools and concepts"}, {"id": "04ec84a3-96af-41c1-9d13-0de029230cec", "type": "concept", "title": "Evaluating sources, using evidence, communicating conclusions, and taking informed action"}], "description": "Students learn the national inquiry architecture behind social studies teaching."}, {"id": "43cb8a2b-21b7-4136-b69b-8ebbd439d5ad", "type": "subtopic", "title": "Standards alignment", "children": [{"id": "686c09c6-6cb7-4204-8d4e-17678ae0440e", "type": "concept", "title": "NCSS themes, state standards, and local curriculum expectations"}, {"id": "15418ba3-bb44-4c9d-840e-6b3ca94f9c84", "type": "concept", "title": "Grade-band progression and vertical coherence"}, {"id": "b5cefbbc-34a0-46cb-a850-18f6f32f3668", "type": "concept", "title": "Learning objectives, success criteria, and standards documentation"}], "description": "The gist is to make standards teachable through coherent learning progressions."}, {"id": "c61b04cb-571f-470d-8bd3-38e317f8bf7c", "type": "subtopic", "title": "Inquiry Design Model", "children": [{"id": "eb0ef324-c2dc-4485-920a-5017f4aa538c", "type": "concept", "title": "Compelling and supporting questions"}, {"id": "e9d43b39-b619-411a-85e0-2ccb2f2f0314", "type": "concept", "title": "Source sets, formative tasks, and summative arguments"}, {"id": "d86e5b2c-71a1-44e8-8918-e69941660df9", "type": "concept", "title": "Informed action and reflection"}], "description": "Students learn to build lessons around compelling questions, sources, tasks, and action."}]}, {"id": "89ac8c88-78e6-4398-8113-d23960e41a61", "type": "topic", "title": "Developmentally Appropriate K-6 Social Studies and Concept Formation", "description": "Students learn how young learners build ideas about time, place, rules, fairness, culture, community, and change.", "children": [{"id": "347e6b84-51fc-4250-9a07-c7eaed8534cf", "type": "subtopic", "title": "Child development and social understanding", "children": [{"id": "07ee3a7f-9b29-4e8f-b25c-0ed32ee3e3d6", "type": "concept", "title": "Understanding time, sequence, fairness, rules, and perspective-taking"}, {"id": "3eb14f06-1bc3-4544-9183-af026447c2a2", "type": "concept", "title": "Concrete-to-abstract reasoning across grades K-6"}, {"id": "ba62cce2-18ed-44c2-be5e-90682e9603a9", "type": "concept", "title": "Social-emotional development and classroom community"}], "description": "Teachers connect social studies concepts to how children reason about self, others, time, and community."}, {"id": "0734a875-13c8-4312-aa66-38e3966c6d7a", "type": "subtopic", "title": "Concept development", "children": [{"id": "df48b4ff-5749-4d8d-a484-8825b1e0ac82", "type": "concept", "title": "Community, culture, authority, conflict, cooperation, and change"}, {"id": "db75a009-cc5d-43c7-b9eb-c88e483e428a", "type": "concept", "title": "Identity, belonging, migration, and interdependence"}, {"id": "46f18195-af8d-4992-9320-1fa86a7b1329", "type": "concept", "title": "Misconceptions and partial understandings"}], "description": "Students learn to teach powerful ideas repeatedly through age-appropriate examples."}, {"id": "404ec7aa-f409-49f4-860d-330ae6aab353", "type": "subtopic", "title": "Pedagogical moves", "children": [{"id": "d280846a-e1e5-40c4-a5ab-acf8bc2de2a0", "type": "concept", "title": "Stories, maps, artifacts, images, timelines, and simulations"}, {"id": "31b744ca-ce2f-4fdc-a0ac-77e63175ffa5", "type": "concept", "title": "Talk, drawing, movement, read-alouds, and dramatic play"}, {"id": "492b8dbd-9506-4f73-8c1e-a09dbb456190", "type": "concept", "title": "Scaffolding vocabulary and background knowledge"}], "description": "Effective elementary social studies uses concrete experiences to build abstract civic and disciplinary ideas."}]}, {"id": "a2150050-0104-45a5-a5b1-ba18c4b9ea2c", "type": "topic", "title": "Geography, Spatial Thinking, Place, Environment, and Human-Environment Interaction", "description": "This topic builds the map, place, region, and environmental reasoning children need to understand communities and the wider world.", "children": [{"id": "50b4d0bf-cd66-4188-8b94-30364eaaae47", "type": "subtopic", "title": "Map and spatial skills", "children": [{"id": "fd48842e-454b-489c-bb6b-ca91fb627834", "type": "concept", "title": "Symbols, scale, direction, distance, grids, and legends"}, {"id": "9ded0542-de22-4a3d-be9e-472df86d2830", "type": "concept", "title": "Mental maps, relative location, and spatial vocabulary"}, {"id": "76b1352d-944a-493e-95d1-16f042040382", "type": "concept", "title": "Introductory GIS, digital maps, and geospatial data"}], "description": "Students learn to make maps tools for reasoning, not decorative classroom objects."}, {"id": "18dfed27-a6c2-419b-8010-213d959b078b", "type": "subtopic", "title": "Place and region", "children": [{"id": "77fcdf84-eaa5-451b-83fb-6e8c64329bef", "type": "concept", "title": "Neighborhood, city, state, nation, and world regions"}, {"id": "ff493605-2850-4f5b-9eca-ee34e0085861", "type": "concept", "title": "Physical features, cultural landscapes, and land use"}, {"id": "949ff1eb-dd16-4f60-8bdb-f9738702c735", "type": "concept", "title": "Comparing places through evidence and perspective"}], "description": "Children learn that places are physical, cultural, historical, and economic at the same time."}, {"id": "47528c91-7f90-4511-a3ec-56047181d5c8", "type": "subtopic", "title": "Human-environment interaction", "children": [{"id": "e08b965a-a806-4338-9ed1-af9151244f41", "type": "concept", "title": "Natural resources, weather, climate, and hazards"}, {"id": "a0842504-e012-494a-83c1-0084a4d76cd5", "type": "concept", "title": "Transportation, settlement, agriculture, and urbanization"}, {"id": "ebbaa907-783b-4db8-a43d-56b4b0df9c27", "type": "concept", "title": "Environmental justice and stewardship"}], "description": "The point is to connect human choices to resources, climate, sustainability, and community life."}]}, {"id": "0da73764-8ac0-479c-8688-dd690ad3f2d4", "type": "topic", "title": "Historical Thinking, Chronology, Primary Sources, and Historical Empathy", "description": "Students learn to teach history as evidence-based interpretation rather than memorized facts.", "children": [{"id": "31112701-d8d8-4d3b-b21e-7ca71489a0d0", "type": "subtopic", "title": "Historical thinking", "children": [{"id": "445cfa92-72cf-43a9-9835-3a9ff17e1892", "type": "concept", "title": "Chronology, continuity, change, cause, and consequence"}, {"id": "7c9ad1fe-1f3f-4391-9891-7bfc95d08740", "type": "concept", "title": "Sourcing, contextualization, corroboration, and close reading"}, {"id": "8948f5ec-3f32-49e6-a3db-da8a97ffc5d4", "type": "concept", "title": "Fact, interpretation, narrative, and argument"}], "description": "Students learn how children can reason historically with evidence and age-appropriate questions."}, {"id": "26bcc33d-4bdd-4c70-958d-e1c76a2579e7", "type": "subtopic", "title": "Primary sources", "children": [{"id": "a9e4ad2d-58c7-4273-8464-0a4e8d80f13c", "type": "concept", "title": "Documents, photographs, maps, objects, songs, art, and oral histories"}, {"id": "d330645b-ba1e-4ba9-b9cb-41bd78a673df", "type": "concept", "title": "Library of Congress and local archive source sets"}, {"id": "9188b3d7-1939-4782-b515-15e600623964", "type": "concept", "title": "Questioning, annotation, and evidence selection"}], "description": "Primary sources let children encounter history as human evidence."}, {"id": "3e9cfcac-20b3-48b5-81bd-634848978f7a", "type": "subtopic", "title": "Historical empathy and perspective", "children": [{"id": "7112ab13-32af-4377-a722-e527b2beb3d7", "type": "concept", "title": "Multiple perspectives and contested memories"}, {"id": "5d5b3929-dee6-4171-8188-65c7fbbaa69f", "type": "concept", "title": "Indigenous, Black, immigrant, labor, gender, disability, and local histories"}, {"id": "41021392-7569-48c1-941b-8d734bf23601", "type": "concept", "title": "Ethical remembrance, harm, agency, and resilience"}], "description": "Students learn to teach perspective-taking without presentism or false equivalence."}]}, {"id": "4cf28ebb-6b69-44af-b3d6-e31b2d644c7a", "type": "topic", "title": "Civics, Government, Rights, Responsibilities, and Democratic Participation", "description": "This module prepares teachers to help children understand rules, institutions, rights, responsibilities, and civic problem solving.", "children": [{"id": "186dbae1-e436-48ef-af27-a6887513cbe5", "type": "subtopic", "title": "Government structures", "children": [{"id": "233bcc09-c3db-4ecc-a42d-26960ccd238e", "type": "concept", "title": "Classroom, school, local, state, tribal, federal, and global governance"}, {"id": "07048153-3acc-4c68-89ef-d9c9171719ab", "type": "concept", "title": "Rules, laws, constitutions, courts, executives, legislatures, and agencies"}, {"id": "2a2bbfbb-a6f7-4582-bec8-98549081d549", "type": "concept", "title": "Public services, public goods, and community helpers"}], "description": "Children build civic understanding from classroom rules and local institutions outward."}, {"id": "3c3ed242-6a69-45c9-9f91-8ca8b28d97e7", "type": "subtopic", "title": "Rights and responsibilities", "children": [{"id": "0ddcaff3-51de-4240-9006-f733c832c846", "type": "concept", "title": "Constitutional principles, civil rights, and liberties"}, {"id": "055030d6-07d4-413d-8bf7-d3ff62a8ba4d", "type": "concept", "title": "Duties, responsibilities, public good, and civic virtue"}, {"id": "4f135793-c188-41b0-a224-2bca04295475", "type": "concept", "title": "Equity, access, due process, and representation"}], "description": "Students learn to connect rights to responsibilities, institutions, and participation."}, {"id": "c09dcbb5-038b-4d79-b3da-44ebfcc9006a", "type": "subtopic", "title": "Democratic practices", "children": [{"id": "01eb5548-f81d-4710-936e-84a0c8eb6132", "type": "concept", "title": "Voting, petitioning, discussion, volunteering, and public problem solving"}, {"id": "3df6fab4-2e28-47c3-88b7-5cc5a16d4bdb", "type": "concept", "title": "Class meetings, classroom democracy, and student voice"}, {"id": "252393d9-3933-4d82-b3b0-97f1df3d92fc", "type": "concept", "title": "Claims, evidence, listening, disagreement, and compromise"}], "description": "Teachers learn to make civic learning active, deliberative, and age appropriate."}]}, {"id": "fffc6d90-6713-4ae0-866f-9bda423e25c4", "type": "topic", "title": "Elementary Economics, Financial Literacy, Scarcity, Choice, and Community Systems", "description": "Students learn to make economic reasoning concrete through wants, needs, resources, tradeoffs, labor, money, and public goods.", "children": [{"id": "daf29dd2-92d8-4642-903e-e8170291e384", "type": "subtopic", "title": "Scarcity and choice", "children": [{"id": "1d1a20f9-9f7d-4c4a-b58b-183c24698c78", "type": "concept", "title": "Wants, needs, goods, services, and resources"}, {"id": "5206d0bf-1ff0-4c1b-8c1f-eb8a2e4df02e", "type": "concept", "title": "Opportunity cost, incentives, and consequences"}, {"id": "fd088f91-b824-47a5-a1db-d0de63573d89", "type": "concept", "title": "Personal, family, classroom, and community choices"}], "description": "The gist is that children can reason about tradeoffs using familiar wants, needs, and resources."}, {"id": "88b04cfd-ccc9-448a-9bd9-ec34dadb5f12", "type": "subtopic", "title": "Markets and community economies", "children": [{"id": "c7d80cd4-57ec-4202-bafe-cbdf78cd193c", "type": "concept", "title": "Producers, consumers, workers, entrepreneurs, and households"}, {"id": "065656f0-dcc5-46de-8d5b-7c1afd849349", "type": "concept", "title": "Prices, markets, supply, demand, and specialization in simple terms"}, {"id": "94deb382-c404-41db-9371-ffe5f58ca3c8", "type": "concept", "title": "Local businesses, community systems, and global supply chains"}], "description": "Students learn to make production, exchange, work, and interdependence visible."}, {"id": "5e1275fc-aa82-4245-b796-e167effceb46", "type": "subtopic", "title": "Money and financial literacy", "children": [{"id": "7ed12ce6-98a0-4517-bb19-997016ef9666", "type": "concept", "title": "Saving, spending, budgeting, borrowing, and sharing"}, {"id": "732f8144-d5ec-4782-9af6-c8f0018caee2", "type": "concept", "title": "Taxes, public goods, and shared services"}, {"id": "9ac27222-b741-40dc-8efb-7ac222e0fb31", "type": "concept", "title": "Advertising, needs versus wants, and consumer decision-making"}], "description": "Elementary economics includes habits for wise personal and civic decision-making."}]}, {"id": "433a0d4a-e220-4143-a758-a41d176492be", "type": "topic", "title": "Culture, Identity, Global Education, and Multiple Perspectives", "description": "This topic centers social studies as a study of people, belonging, migration, interdependence, and diverse ways of seeing the world.", "children": [{"id": "235151d6-3dd4-4b8c-a4d1-f9efd0fbc083", "type": "subtopic", "title": "Culture and identity", "children": [{"id": "4cadee0c-d487-4409-b12a-7fbad2e9be54", "type": "concept", "title": "Family, language, religion, foodways, traditions, migration, and identity"}, {"id": "bdef7d7b-254b-4836-9670-33fd1f4443cb", "type": "concept", "title": "Funds of knowledge and community expertise"}, {"id": "d8ebc757-d76b-4cbe-a218-eeea81be4367", "type": "concept", "title": "Avoiding stereotypes and single stories"}], "description": "Students learn to teach culture as dynamic lived practice rather than static traits."}, {"id": "f184aedd-f76d-4a0e-9113-9b479333578e", "type": "subtopic", "title": "Global education", "children": [{"id": "c28ce05e-36c6-4431-8a2b-bd38db4dbf0d", "type": "concept", "title": "World regions, global interdependence, migration, trade, and environment"}, {"id": "0314f5af-1187-443c-bab2-260a4f0bf348", "type": "concept", "title": "Comparative perspectives without ranking cultures"}, {"id": "78ce7e77-8837-4576-8f63-ec5130254f71", "type": "concept", "title": "Global citizenship, human rights, and sustainability"}], "description": "Children learn that local life is connected to world regions, systems, and people."}, {"id": "1d54db27-7156-48f4-8c7b-258df1e7b6c4", "type": "subtopic", "title": "Multiple perspectives", "children": [{"id": "3cad8022-2f78-4b31-8d4b-4f8566f1b041", "type": "concept", "title": "Indigenous, Black, Latinx, Asian American, immigrant, disability, gender, and class perspectives"}, {"id": "c429f45d-3eb1-4834-97c9-d8a41d8b4e4a", "type": "concept", "title": "Perspective-taking, positionality, and source authorship"}, {"id": "f8f199a8-d1a9-4b96-826c-1322fe96953c", "type": "concept", "title": "Inclusive texts, images, maps, examples, and classroom discourse"}], "description": "Social studies becomes stronger when children study whose voices are centered, missing, or contested."}]}, {"id": "2a9e8ac5-f80f-450c-aed5-790a60006e58", "type": "topic", "title": "Current Events, Media Literacy, Controversial Issues, and Civic Discourse", "description": "Students learn to bring the world into the classroom with care, evidence, age-appropriate discussion, and community norms.", "children": [{"id": "77a5f681-18ee-4465-abf9-21cc7a9bf846", "type": "subtopic", "title": "News and media literacy", "children": [{"id": "cbbf8592-dae4-4bc6-83c3-48ab1f09d1d6", "type": "concept", "title": "Source credibility, evidence, bias, propaganda, and misinformation"}, {"id": "7a9d714b-a3d7-451b-8089-b7e8a82d2998", "type": "concept", "title": "Lateral reading, fact-checking, and age-appropriate news sources"}, {"id": "bcec22a4-6c1f-43fd-9cf2-18eb825eef47", "type": "concept", "title": "Images, charts, maps, headlines, algorithms, and social media"}], "description": "Students learn to help children ask who made a message, what evidence supports it, and what might be missing."}, {"id": "83f213f0-3dd4-4f8a-9c36-e2c2669b645f", "type": "subtopic", "title": "Controversial issues pedagogy", "children": [{"id": "b88a5e5d-8174-49ce-9cc5-ed714529f428", "type": "concept", "title": "Issue selection, family/community context, and classroom readiness"}, {"id": "47b50012-cfe0-41c2-a153-9f0434e06e0f", "type": "concept", "title": "Structured academic controversy and discussion protocols"}, {"id": "2a912096-7777-49f0-a99a-fa94f402d40a", "type": "concept", "title": "Trauma-informed facilitation and de-escalation"}], "description": "The point is to discuss real issues without sacrificing care, accuracy, or developmental appropriateness."}, {"id": "a10d1686-bf4d-448b-a40f-2c9a106d0999", "type": "subtopic", "title": "Civic discourse", "children": [{"id": "3309185f-960a-4d0f-a365-77fbf8805e2f", "type": "concept", "title": "Claims, evidence, reasoning, questions, and counterarguments"}, {"id": "3fea0d24-5b28-43aa-a7e9-fabe2834dab5", "type": "concept", "title": "Norms for listening, turn-taking, and respectful disagreement"}, {"id": "c8f09a24-9605-4e96-93ed-82a5a889844e", "type": "concept", "title": "Public audience, civic writing, and informed action"}], "description": "Children practice democracy by learning to listen, reason, disagree, and revise."}]}, {"id": "771cf2b7-6683-475f-8d9d-4231f3731b19", "type": "topic", "title": "Teaching for Social Justice, Equity, Anti-Bias Education, and Inclusive Social Studies", "description": "This module helps teachers build social studies classrooms where all learners can examine identity, power, justice, and action responsibly.", "children": [{"id": "7e910b77-db51-4f14-ab2d-cd974e615308", "type": "subtopic", "title": "Anti-bias frameworks", "children": [{"id": "df2023ae-8761-4200-9449-4a5d72678501", "type": "concept", "title": "Learning for Justice social justice standards"}, {"id": "9009599a-5875-4c83-b31c-87c5ad080ea7", "type": "concept", "title": "Identity safety, belonging, and brave conversations"}, {"id": "443a13c8-4cda-4625-9d0e-e4b4747553ef", "type": "concept", "title": "Bias, stereotypes, privilege, exclusion, and repair"}], "description": "Students learn to connect identity, diversity, justice, and action in age-appropriate ways."}, {"id": "e1cec6ef-1b25-480e-9f9b-53d85d70162b", "type": "subtopic", "title": "Culturally responsive and sustaining teaching", "children": [{"id": "9337fa68-603b-4b4d-87dc-25fd97abe941", "type": "concept", "title": "Funds of knowledge and community cultural wealth"}, {"id": "baa0cc1e-7cc7-482c-a5c1-53330ca9a7be", "type": "concept", "title": "Culturally sustaining texts, examples, questions, and tasks"}, {"id": "bbf94b7b-e36e-465e-9418-fb5f4ae1b22f", "type": "concept", "title": "Family partnerships and local knowledge"}], "description": "Teachers learn to make social studies relevant, rigorous, and connected to students' communities."}, {"id": "ef40eee2-9fb0-4d43-9246-7871668944ca", "type": "subtopic", "title": "Inclusive and accessible social studies", "children": [{"id": "e39fafa4-4816-475a-9cd5-424f086f9efc", "type": "concept", "title": "Universal Design for Learning and differentiated access"}, {"id": "306306ef-2688-497c-b8f2-e24fe84e2735", "type": "concept", "title": "Multilingual supports, translanguaging, and academic vocabulary"}, {"id": "28b7ca00-9040-4120-baff-1857b095e020", "type": "concept", "title": "Assistive technology, sensory needs, trauma-informed supports, and participation choices"}], "description": "Social studies must be designed for multilingual learners, disabled learners, and varied ways of participating."}]}, {"id": "6604dbf5-881c-44a9-b50c-b65690218d7b", "type": "topic", "title": "Interdisciplinary Integration: Literacy, Arts, STEM, Local Studies, and Project-Based Learning", "description": "Students learn to connect social studies with reading, writing, visual culture, data, design, local inquiry, and authentic projects.", "children": [{"id": "32ba9381-8bc5-4cfa-8fe6-b8f5272cad46", "type": "subtopic", "title": "Literacy integration", "children": [{"id": "4943ead4-4cd1-4b83-b855-fe1757d844fd", "type": "concept", "title": "Read-alouds, children's literature, informational texts, and source reading"}, {"id": "fa648754-c5c1-4fbf-bf32-3169d9f57caa", "type": "concept", "title": "Academic vocabulary, discussion, evidence-based writing, and argument"}, {"id": "777844c6-036f-4952-8b7f-b1267e54e9c3", "type": "concept", "title": "Text sets, book choice, and culturally inclusive libraries"}], "description": "Social studies builds reading, writing, speaking, listening, and vocabulary through meaningful content."}, {"id": "48a77bba-9bc7-4367-b699-2b96f925f1b4", "type": "subtopic", "title": "Arts and STEM integration", "children": [{"id": "23a4f10e-93a3-4f15-8b3b-c6eefaeaf42a", "type": "concept", "title": "Timelines, data displays, maps, graphs, and measurement"}, {"id": "dc151f9c-3c26-4477-ab44-4b2f0d7e1d16", "type": "concept", "title": "Music, art, drama, monuments, material culture, and visual analysis"}, {"id": "649e0488-3c26-4ab2-a223-a9a032bd11cd", "type": "concept", "title": "Design challenges, sustainability problems, and civic data inquiry"}], "description": "Students learn to use visual, quantitative, spatial, and design thinking to deepen social studies."}, {"id": "71f9f5e6-0a2e-4c3e-838c-1c1fc1eced02", "type": "subtopic", "title": "Project-based and local studies", "children": [{"id": "183cd139-6063-4e36-ac48-b2c4b67b9040", "type": "concept", "title": "Neighborhood walks, oral history, museums, archives, and community experts"}, {"id": "3e25c99b-1978-4288-904f-854c7d7c27ec", "type": "concept", "title": "Public problems, design questions, and project products"}, {"id": "45b62a54-5ece-45b7-bd43-8b8df961ff23", "type": "concept", "title": "Student voice, authentic audience, and reflection"}], "description": "Local inquiry makes abstract civic and historical concepts visible and actionable."}]}, {"id": "9eb67ec7-073b-4c46-8518-626555808b74", "type": "topic", "title": "Lesson and Unit Design: Backward Design, Inquiry Lessons, Fieldwork, and Service Learning", "description": "This topic converts methods knowledge into teachable lessons, sequences, community experiences, and action-oriented inquiry units.", "children": [{"id": "5db4df10-00ab-48f2-8fab-90d767329bad", "type": "subtopic", "title": "Backward design", "children": [{"id": "03edefa6-7d99-4deb-b9c0-d13741a5778c", "type": "concept", "title": "Essential questions, objectives, and success criteria"}, {"id": "8ea0634f-5f23-4f40-ae7f-b861148de6da", "type": "concept", "title": "Assessment before activity selection"}, {"id": "2ac58c23-9ef1-4090-b2d8-6eae7d330760", "type": "concept", "title": "Alignment among standards, tasks, sources, and supports"}], "description": "Students learn to begin with enduring understandings, evidence of learning, and meaningful outcomes."}, {"id": "e3d537ad-2148-4335-bf65-4771b85602e7", "type": "subtopic", "title": "Lesson methods", "children": [{"id": "e27e0380-54c9-4c97-8667-8d42f00ac7d6", "type": "concept", "title": "Source analysis, map inquiry, simulations, role play, debate, and discussion"}, {"id": "a55ee9a1-2a89-419a-bb85-ea941d2dbe2f", "type": "concept", "title": "Mini-lessons, modeling, guided inquiry, collaborative tasks, and reflection"}, {"id": "cddf1513-4611-4bf6-a4dd-a83628f43bb2", "type": "concept", "title": "Differentiation for readiness, language, access, and interest"}], "description": "Teachers practice a repertoire of methods for inquiry-rich elementary social studies."}, {"id": "6a260795-547d-4ffd-925b-09c58b8329d9", "type": "subtopic", "title": "Fieldwork and service learning", "children": [{"id": "10d568ed-b985-4484-9278-60d90b303301", "type": "concept", "title": "Community walks, guest speakers, museums, civic offices, and virtual field trips"}, {"id": "f7355436-367c-4f81-8ec6-d1bb9a4996c9", "type": "concept", "title": "Service learning, civic action, and public products"}, {"id": "7a0535b7-7367-4f8f-8346-7a6b6e3318b3", "type": "concept", "title": "Safety, permissions, accessibility, and ethical community partnership"}], "description": "Social studies grows when children investigate and serve real communities."}]}, {"id": "55fb9e2a-7dc7-4b0f-a043-4af50253a59e", "type": "topic", "title": "Assessment in Social Studies: Formative Checks, Rubrics, Portfolios, and Performance Tasks", "description": "Students learn to assess social studies understanding through evidence, reasoning, products, reflection, and participation.", "children": [{"id": "81a1170f-c708-4a69-aee0-d40e687094b5", "type": "subtopic", "title": "Formative assessment", "children": [{"id": "4edc2b08-f246-4752-a48e-1686d4712169", "type": "concept", "title": "Exit tickets, concept maps, turn-and-talks, observation notes, and quick writes"}, {"id": "2c0106db-348b-4321-8b48-159686e796cc", "type": "co